+// NewPortStat parses an IP address and port, preserving brackets around IPv6 addresses.
+func NewPortStat(ipPort string) (*PortStat, error) {
+	stat := &PortStat{}
+	if ipPort == "" {
+		return stat, nil
+	}
+	host, port, err := net.SplitHostPort(ipPort)
+	portNumber, portErr := strconv.Atoi(port)
+	if err != nil || host == "" || portErr != nil || portNumber < 1 || portNumber > 65535 || (host != "*" && net.ParseIP(host) == nil) {
